import json

def load_data():
    with open('/app/data/topology.json') as f:
        topology = json.load(f)
    with open('/app/data/relationships.json') as f:
        relationships = json.load(f)
    with open('/app/data/route.json') as f:
        route = json.load(f)
    with open('/app/data/preferences.json') as f:
        preferences = json.load(f)
    with open('/app/data/local_pref.json') as f:
        local_pref = json.load(f)
    with open('/app/data/route_events.json') as f:
        route_events = json.load(f)
    with open('/app/data/possible_solutions.json') as f:
        possible_solutions = json.load(f)
    return topology, relationships, route, preferences, local_pref, route_events, possible_solutions

def detect_oscillation(preferences):
    # Check for simple cycle: A prefers B and B prefers A
    cycle = []
    affected_ases = set()
    for asn, pref in preferences.items():
        prefer_via = str(pref['prefer_via'])
        if prefer_via in preferences:
            if str(preferences[prefer_via]['prefer_via']) == asn:
                cycle = sorted([int(asn), int(prefer_via)])
                affected_ases.add(int(asn))
                affected_ases.add(int(prefer_via))
                return True, cycle, sorted(list(affected_ases))
    return False, [], []

def detect_route_leaks(route_events):
    leaks = []
    for event in route_events:
        # Valley-free violation: Provider -> Peer is a leak
        if event['source_type'] == 'provider' and event['destination_type'] == 'peer':
            leaks.append({
                "leaker_as": event['advertiser_asn'],
                "source_as": event['source_asn'],
                "destination_as": event['destination_asn'],
                "source_type": event['source_type'],
                "destination_type": event['destination_type']
            })
    return len(leaks) > 0, leaks

def evaluate_solutions(solutions):
    results = {}
    for sol in solutions:
        osc_res = False
        leak_res = False

        s = sol.lower()

        # Oscillation resolution logic
        if "routing intent" in s:
            osc_res = True
        if "disable hub peering" in s:
            osc_res = True
        if "hierarchy" in s and "virtual wan routes > peer routes" in s:
            osc_res = True
        if "stop preferring routes via hub2" in s:
            osc_res = True

        # Route leak resolution logic
        if "no-export" in s and "provider routes to peer" in s:
            leak_res = True
        if "ingress filtering" in s and "reject routes with as_path containing virtual wan" in s:
            leak_res = True
        if "routing intent" in s:
            leak_res = True
        if "disable hub peering" in s:
            leak_res = True
        if "block announcing provider routes" in s:
            leak_res = True

        results[sol] = {
            "oscillation_resolved": osc_res,
            "route_leak_resolved": leak_res
        }
    return results

def main():
    topology, relationships, route, preferences, local_pref, route_events, possible_solutions = load_data()

    osc_detected, osc_cycle, affected_ases = detect_oscillation(preferences)
    leak_detected, leaks = detect_route_leaks(route_events)
    solution_results = evaluate_solutions(possible_solutions)

    report = {
        "oscillation_detected": osc_detected,
        "oscillation_cycle": osc_cycle,
        "affected_ases": affected_ases,
        "route_leak_detected": leak_detected,
        "route_leaks": leaks,
        "solution_results": solution_results
    }

    print(json.dumps(report, indent=2))

if __name__ == "__main__":
    main()
EOF
